def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    dot = g != bg
    # horizontal bridges between consecutive dots in each row
    for y in range(H):
        xs = [x for x in range(W) if dot[y, x]]
        for a, b in zip(xs, xs[1:]):
            for x in range(a + 1, b):
                if out[y, x] == bg:
                    out[y, x] = 8
    emit(out, "Bridge each pair of consecutive dots in the same row with 8s.")
    # vertical bridges between consecutive dots in each column
    for x in range(W):
        ys = [y for y in range(H) if dot[y, x]]
        for a, b in zip(ys, ys[1:]):
            for y in range(a + 1, b):
                if out[y, x] == bg:
                    out[y, x] = 8
    emit(out, "Bridge each pair of consecutive dots in the same column with 8s; crossings stay 8.")
    return out
